"""生成与现有 SVG 占位美术一致的剧情道具；会覆盖同名道具。"""
from pathlib import Path
base=Path(__file__).resolve().parents[1]/'assets/portraits'
def save(name,body):
    defs='<defs><linearGradient id="gold" x2="0" y2="1"><stop stop-color="#f8dc91"/><stop offset="1" stop-color="#b8833e"/></linearGradient><linearGradient id="wood" x2="0" y2="1"><stop stop-color="#a07659"/><stop offset="1" stop-color="#604b40"/></linearGradient><radialGradient id="light"><stop stop-color="#fff8cf"/><stop offset="1" stop-color="#ffe39b" stop-opacity="0"/></radialGradient></defs>'
    (base/(name+'.svg')).write_text('<svg xmlns="http://www.w3.org/2000/svg" width="360" height="420" viewBox="0 0 360 420">'+defs+body+'</svg>')
chest='<ellipse cx="180" cy="372" rx="144" ry="15" fill="#38493b" opacity=".18"/><path d="M49 255L311 255L295 356Q180 383 66 354Z" fill="url(#wood)" stroke="#564538" stroke-width="5"/><path d="M64 286L298 286M66 319L297 319" stroke="#c19362" stroke-width="3"/><path d="M68 259L83 356M279 260L271 360" stroke="url(#gold)" stroke-width="16"/><path d="M62 351Q180 376 296 354" stroke="#d2a660" fill="none" stroke-width="9"/><rect x="161" y="270" width="39" height="51" rx="7" fill="url(#gold)" stroke="#765c3b" stroke-width="3"/><circle cx="181" cy="287" r="6" fill="#63513c"/><path d="M181 287v16" stroke="#63513c" stroke-width="5"/>'
